74i","tree":{"sha":"5307cc91ca0a4a3af7953e99637899ee31ff6aff","url":"https://api.github.com/repos/archi-duke/GoJIRA/git/trees/5307cc91ca0a4a3af7953e99637899ee31ff6aff"},"url":"https://api.github.com/repos/archi-duke/GoJIRA/git/commits/089d449d2ca2163f959dd2df0267dcf0bc6d827e","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/222582245?v=4","events_url":"https://api.github.com/users/dkdoc7/events{/privacy}","followers_url":"https://api.github.com/users/dkdoc7/followers","following_url":"https://api.github.com/users/dkdoc7/following{/other_user}","gists_url":"https://api.github.com/users/dkdoc7/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/dkdoc7","id":222582245,"login":"dkdoc7","node_id":"U_kgDODURV5Q","organizations_url":"https://api.github.com/users/dkdoc7/orgs","received_events_url":"https://api.github.com/users/dkdoc7/received_events","repos_url":"https://api.github.com/users/dkdoc7/repos","site_admin":false,"starred_url":"https://api.github.com/users/dkdoc7/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/dkdoc7/subscriptions","type":"User","url":"https://api.github.com/users/dkdoc7","user_view_type":"public"},"html_url":"https://github.com/archi-duke/GoJIRA/commit/089d449d2ca2163f959dd2df0267dcf0bc6d827e","node_id":"C_kwDORyCU2NoAKDA4OWQ0NDlkMmNhMjE2M2Y5NTlkZDJkZjAyNjdkY2YwYmM2ZDgyN2U","parents":[{"html_url":"https://github.com/archi-duke/GoJIRA/commit/bf2ce9494aca3d2982b9b531d8244194c4f31cac","sha":"bf2ce9494aca3d2982b9b531d8244194c4f31cac","url":"https://api.github.com/repos/archi-duke/GoJIRA/commits/bf2ce9494aca3d2982b9b531d8244194c4f31cac"}],"sha":"089d449d2ca2163f959dd2df0267dcf0bc6d827e","url":"https://api.github.com/repos/archi-duke/GoJIRA/commits/089d449d2ca2163f959dd2df0267dcf0bc6d827e"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/222582245?v=4","events_url":"https://